contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint creditBefore = amount;
        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint creditAfter = 0;
        uint contractBalanceAfter = address(c).balance;

        assert(
            (creditBefore > 0 && contractBalanceBefore >= creditBefore && !reverted && contractBalanceAfter == contractBalanceBefore - creditBefore) ||
            (creditBefore > 0 && contractBalanceBefore >= creditBefore && reverted) ||
            (creditBefore > 0 && contractBalanceBefore < creditBefore && creditAfter == creditBefore && reverted)
        );
    }

    receive() external payable {}
}

