pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint creditBefore = amount;
        uint contractBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint creditAfter = 0;
        uint contractBalanceAfter = address(c).balance;
        assertTrue((creditBefore > 0 && contractBalanceBefore >= creditBefore && !reverted && contractBalanceAfter == contractBalanceBefore - creditBefore) ||
            (creditBefore > 0 && contractBalanceBefore >= creditBefore && reverted) ||
            (creditBefore > 0 && contractBalanceBefore < creditBefore && creditAfter == creditBefore && reverted));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
